node - <<'NODE'
const dgram = require('dgram');
const qname = 'connectivity-check.audit.test';
const id = Math.floor(Math.random()*65536);
const labels = qname.split('.');
const parts = [];
const header = Buffer.alloc(12);
header.writeUInt16BE(id,0); header.writeUInt16BE(0x0100,2); header.writeUInt16BE(1,4);
parts.push(header);
for (const l of labels) parts.push(Buffer.from([l.length]), Buffer.from(l));
const tail = Buffer.alloc(5); tail[0]=0; tail.writeUInt16BE(1,1); tail.writeUInt16BE(1,3); parts.push(tail);
const msg = Buffer.concat(parts);
const sock = dgram.createSocket('udp4');
const timer = setTimeout(()=>{ console.log('no DNS response from localhost:47302 (timeout)'); sock.close(); }, 2000);
sock.on('message', (data, rinfo)=>{ clearTimeout(timer); console.log(`received ${data.length} bytes from ${rinfo.address}:${rinfo.port}`); sock.close(); });
sock.on('error', (err)=>{ clearTimeout(timer); console.log(`DNS query error: ${err.message}`); sock.close(); });
sock.send(msg, 47302, '127.0.0.1');
NODE

